import{_ as s}from"./chunks/plugin-vue_export-helper.DlAUqK2U.js";import{c as a,o as i,af as t}from"./chunks/mermaid.DEOxUarQ.js";import"./chunks/cytoscape.C2CwDKBM.js";import"./chunks/dayjs.C32PoDnw.js";const m=JSON.parse('{"title":"GLM Coding Plan 实战手册","description":"已经订好套餐之后：按官方原文切换 GLM-5.3、加套餐 MCP、处理 1113 与团队 Key。","frontmatter":{"title":"GLM Coding Plan 实战手册","description":"已经订好套餐之后：按官方原文切换 GLM-5.3、加套餐 MCP、处理 1113 与团队 Key。","domain":"product","tags":["coding-plan"],"role":"cookbook"},"headers":[],"relativePath":"zh/products/glm-coding/glm-coding-cookbook.md","filePath":"zh/products/glm-coding/glm-coding-cookbook.md","lastUpdated":1787110548000}'),n={name:"zh/products/glm-coding/glm-coding-cookbook.md"};function o(l,e,d,r,p,h){return i(),a("div",null,[...e[0]||(e[0]=[t(`<h1 id="glm-coding-plan-实战手册" tabindex="-1">GLM Coding Plan 实战手册 <a class="header-anchor" href="#glm-coding-plan-实战手册" aria-label="Permalink to &quot;GLM Coding Plan 实战手册&quot;">​</a></h1><p>面向已经订上套餐、工具能连上的读者。每个配方只解决一个问题。还没接到工具，先看 <a href="./glm-coding.html">教程</a>。</p><h2 id="_1-切到当前套餐模型-glm-5-3" tabindex="-1">1. 切到当前套餐模型（GLM-5.3） <a class="header-anchor" href="#_1-切到当前套餐模型-glm-5-3" aria-label="Permalink to &quot;1. 切到当前套餐模型（GLM-5.3）&quot;">​</a></h2><p>事实源：<a href="https://docs.bigmodel.cn/cn/coding-plan/latest-model" target="_blank" rel="noreferrer">如何切换模型</a>。overview / FAQ：所有套餐已支持 <strong>GLM-5.3</strong>、GLM-5-Turbo、GLM-4.7。</p><p><code>tool/claude</code> 的 FAQ 仍写 GLM-4.7 / GLM-4.5-Air 映射。<strong>切模型不要抄那张旧表。</strong></p><p>开始前确认：</p><ol><li>套餐有效，Key 能用。</li><li>端点正确： <ul><li>Claude Code / Goose（Anthropic）：<code>https://open.bigmodel.cn/api/anthropic</code></li><li>Codex：<code>https://open.bigmodel.cn/api/v1</code>（<code>latest-model</code> 原文；国内 <a href="https://docs.bigmodel.cn/cn/coding-plan/tool/others" target="_blank" rel="noreferrer">适用工具</a> 卡未列入 Codex）</li><li>其它 OpenAI 兼容：<code>https://open.bigmodel.cn/api/coding/paas/v4</code></li></ul></li></ol><h3 id="claude-code" tabindex="-1">Claude Code <a class="header-anchor" href="#claude-code" aria-label="Permalink to &quot;Claude Code&quot;">​</a></h3><p>在 <code>~/.claude/settings.json</code>（Windows：<code>%USERPROFILE%\\.claude\\settings.json</code>）加入或替换：</p><div class="language-json vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">json</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;env&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: {</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">    &quot;CLAUDE_CODE_AUTO_COMPACT_WINDOW&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;1000000&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">    &quot;ANTHROPIC_DEFAULT_HAIKU_MODEL&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;glm-4.7&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">    &quot;ANTHROPIC_DEFAULT_SONNET_MODEL&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;glm-5.3[1m]&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">    &quot;ANTHROPIC_DEFAULT_OPUS_MODEL&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;glm-5.3[1m]&quot;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  }</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre></div><p>1M 上下文必须带 <code>[1m]</code> 后缀，并设置上面的 <code>CLAUDE_CODE_AUTO_COMPACT_WINDOW</code>。若提示模型不存在，先 <code>claude update</code>。</p><p>新开终端，跑 <code>claude</code>，输入 <code>/status</code>：Settings source 应指向你的 <code>settings.json</code>，Model 显示 <code>glm-5.3</code> 或 <code>glm-5.3[1m]</code>。</p><p>会话里用 <code>/effort</code> 切思考强度，默认 max。关闭思考会被转成 low，<strong>不会</strong>换模型（<code>latest-model</code> 原文）。</p><h3 id="cline-一类自定义模型工具" tabindex="-1">Cline 一类自定义模型工具 <a class="header-anchor" href="#cline-一类自定义模型工具" aria-label="Permalink to &quot;Cline 一类自定义模型工具&quot;">​</a></h3><p><code>latest-model</code> 以 Cline 为例：</p><ul><li>API Provider：<code>OpenAI Compatible</code></li><li>Base URL：<code>https://open.bigmodel.cn/api/coding/paas/v4</code></li><li>模型：自定义，如 <code>glm-5.3</code></li><li>取消勾选 Support Images</li><li>Context Window Size：<code>1000000</code></li></ul><p>不能自定义模型的 Agent：官方写明只能等后续支持。</p><h2 id="_2-给-claude-code-加套餐-mcp" tabindex="-1">2. 给 Claude Code 加套餐 MCP <a class="header-anchor" href="#_2-给-claude-code-加套餐-mcp" aria-label="Permalink to &quot;2. 给 Claude Code 加套餐 MCP&quot;">​</a></h2><p>所有档位都支持视觉、联网搜索、网页读取、开源仓库 MCP，与模型<strong>共享</strong>套餐积分（<a href="https://docs.bigmodel.cn/cn/coding-plan/faq" target="_blank" rel="noreferrer">FAQ</a>）。除套餐包外，官方暂未提供其它调用这些 MCP 的接入方案。</p><p>个人用套餐概览里的 Key；团队必须用团队套餐 Key。</p><h3 id="视觉理解-本地-z-ai-mcp-server" tabindex="-1">视觉理解（本地 <code>@z_ai/mcp-server</code>） <a class="header-anchor" href="#视觉理解-本地-z-ai-mcp-server" aria-label="Permalink to &quot;视觉理解（本地 \`@z_ai/mcp-server\`）&quot;">​</a></h3><p>来源：<a href="https://docs.bigmodel.cn/cn/coding-plan/mcp/vision-mcp-server" target="_blank" rel="noreferrer">vision-mcp-server</a>。需要 <code>&gt;= 0.1.2</code>。老缓存可删 npx cache，或强制 <code>@z_ai/mcp-server@latest</code>。</p><p>Claude Code 用套餐时，服务端已内置 <code>image_analysis</code>。要全套视觉工具再装：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">claude</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> mcp</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> add</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -s</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> user</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> zai-mcp-server</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --env</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> Z_AI_API_KEY=YOUR_API_KEY</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> npx</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -y</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;@z_ai/mcp-server&quot;</span></span></code></pre></div><p>重装前：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">claude</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> mcp</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> list</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">claude</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> mcp</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> remove</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> zai-mcp-server</span></span></code></pre></div><p>国内手配时设 <code>Z_AI_MODE=ZHIPU</code>。<code>Z_AI_MODE</code> 可选 <code>ZHIPU</code> 或 <code>ZAI</code>。</p><p>官方原文：除 Claude Code 外，「直接在客户端粘贴图片无法调用此 MCP Server」；最佳实践是把图片放在当前目录，用路径点名（例如 <code>What does demo.png describe?</code>）。</p><h3 id="联网搜索-remote" tabindex="-1">联网搜索（Remote） <a class="header-anchor" href="#联网搜索-remote" aria-label="Permalink to &quot;联网搜索（Remote）&quot;">​</a></h3><p>来源：<a href="https://docs.bigmodel.cn/cn/coding-plan/mcp/search-mcp-server" target="_blank" rel="noreferrer">search-mcp-server</a>。Claude Code 用套餐时服务端已内置搜索；给其它模型再用：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">claude</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> mcp</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> add</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -s</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> user</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -t</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> http</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> web-search-prime</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> https://open.bigmodel.cn/api/mcp/web_search_prime/mcp</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --header</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;Authorization: Bearer YOUR_API_KEY&quot;</span></span></code></pre></div><h3 id="开源仓库-zread-remote" tabindex="-1">开源仓库 Zread（Remote） <a class="header-anchor" href="#开源仓库-zread-remote" aria-label="Permalink to &quot;开源仓库 Zread（Remote）&quot;">​</a></h3><p>来源：<a href="https://docs.bigmodel.cn/cn/coding-plan/mcp/zread-mcp-server" target="_blank" rel="noreferrer">zread-mcp-server</a>。</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">claude</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> mcp</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> add</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -s</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> user</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -t</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> http</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> zread</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> https://open.bigmodel.cn/api/mcp/zread/mcp</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --header</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;Authorization: Bearer YOUR_API_KEY&quot;</span></span></code></pre></div><p>网页读取 MCP 的命令以 <a href="https://docs.bigmodel.cn/cn/coding-plan/mcp/reader-mcp-server" target="_blank" rel="noreferrer">reader-mcp-server</a> 为准，本页不另抄。</p><h2 id="_3-报错-1113-余额不足-或开始扣账户余额" tabindex="-1">3. 报错 <code>1113 余额不足</code> 或开始扣账户余额 <a class="header-anchor" href="#_3-报错-1113-余额不足-或开始扣账户余额" aria-label="Permalink to &quot;3. 报错 \`1113 余额不足\` 或开始扣账户余额&quot;">​</a></h2><p>来源：<a href="https://docs.bigmodel.cn/cn/coding-plan/faq" target="_blank" rel="noreferrer">FAQ</a>。官方把这类报错归为<strong>未满足套餐使用条件</strong>：</p><ol><li>工具必须在 <a href="https://docs.bigmodel.cn/cn/coding-plan/tool/others#%E4%B8%80%E3%80%81%E9%80%82%E7%94%A8%E5%B7%A5%E5%85%B7" target="_blank" rel="noreferrer">指定名单</a> 里。</li><li>Base URL 必须是套餐端点： <ul><li>Claude Code：<code>https://open.bigmodel.cn/api/anthropic</code></li><li>Cherry Studio：<code>https://open.bigmodel.cn/api/coding/paas/v4/</code></li><li>其它工具：<code>https://open.bigmodel.cn/api/coding/paas/v4</code></li></ul></li><li>官网体验中心不支持编码套餐。</li></ol><p>是否扣的是编码套餐：到 <a href="https://bigmodel.cn/finance/expensebill/list" target="_blank" rel="noreferrer">费用明细</a> 看抵扣资源包。</p><p>额度耗尽后应等待下一个 5 小时周期，系统<strong>不会</strong>自动改扣资源包 / 余额。若仍在扣余额，先查端点，不要加钱试。</p><p>套餐过期后：Claude Code <strong>暂不支持</strong>其它资源包；其它编码工具把 Base URL 改成 <code>https://open.bigmodel.cn/api/paas/v4</code> 才能走资源包（FAQ 原文）。那已经不是套餐额度。</p><h2 id="_4-helper-装不上-网络错误" tabindex="-1">4. Helper 装不上 / 网络错误 <a class="header-anchor" href="#_4-helper-装不上-网络错误" aria-label="Permalink to &quot;4. Helper 装不上 / 网络错误&quot;">​</a></h2><p>来源：<a href="https://docs.bigmodel.cn/cn/coding-plan/extension/coding-tool-helper" target="_blank" rel="noreferrer">coding-tool-helper</a>。</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">coding-helper</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> doctor</span></span></code></pre></div><table tabindex="0"><thead><tr><th>症状</th><th>官方做法</th></tr></thead><tbody><tr><td><code>Network Error</code></td><td>查网络；Node <strong>不会</strong>自动用系统代理，要设 <code>HTTP_PROXY</code> / <code>HTTPS_PROXY</code></td></tr><tr><td>安装超时</td><td>查网络 / 代理，或换国内 npm 源</td></tr><tr><td><code>EACCES: permission denied</code></td><td><code>sudo</code>、管理员终端、改用 <code>npx @z_ai/coding-helper</code>、或 nvm</td></tr><tr><td><code>droid: command not found</code></td><td>把 Factory Droid 可执行路径加进 PATH</td></tr><tr><td>Claude Code 插件市场状态不对</td><td><code>claude update</code> 到 <strong>2.0.70+</strong></td></tr><tr><td>API Key 无效</td><td>核对复制；官方还写了检查账户余额</td></tr></tbody></table><p>代理示例（官方原文结构）：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">export</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> HTTP_PROXY</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">http://your.proxy.server:port</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">export</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> HTTPS_PROXY</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">http://your.proxy.server:port</span></span></code></pre></div><h2 id="_5-团队席位与两把-key" tabindex="-1">5. 团队席位与两把 Key <a class="header-anchor" href="#_5-团队席位与两把-key" aria-label="Permalink to &quot;5. 团队席位与两把 Key&quot;">​</a></h2><p>来源：<a href="https://docs.bigmodel.cn/cn/coding-plan/team" target="_blank" rel="noreferrer">team</a>。</p><ul><li>每位成员加入团队后，在「团队编程套餐」取<strong>自己的</strong>团队套餐 Key。</li><li>个人套餐和团队套餐可以同时存在；同一团队里一人同时只有一个生效席位。</li><li>主管理员默认<strong>不占席位</strong>。要用席位额度，给自己分配一个席位。</li><li>2 席起购；不可多人共用同一席位；标准版与高级版席位暂不可混买。</li><li>额度按席位单独限制。管理员可开超额按量（限时按 <a href="https://bigmodel.cn/pricing" target="_blank" rel="noreferrer">API 刊例价</a> 9 折，以团队页当时说明为准）。</li><li>个人并发建议：Lite 单项目；Pro 1–2 个；Max 2+。团队：标准版 1–2；高级版 2+（<a href="https://docs.bigmodel.cn/cn/coding-plan/usage-notes" target="_blank" rel="noreferrer">usage-notes</a>、team）。</li></ul><p>取消自动续费：个人在 <a href="https://www.bigmodel.cn/coding-plan/personal/overview" target="_blank" rel="noreferrer">套餐概览</a> 操作，须在下一扣费日<strong>至少 3 天前</strong>。订阅一经购买不支持退款（<a href="https://docs.bigmodel.cn/cn/coding-plan/usage-notes" target="_blank" rel="noreferrer">usage-notes</a>）。</p><h2 id="_6-cursor-自定义模型被拒" tabindex="-1">6. Cursor 自定义模型被拒 <a class="header-anchor" href="#_6-cursor-自定义模型被拒" aria-label="Permalink to &quot;6. Cursor 自定义模型被拒&quot;">​</a></h2><p>国内 Cursor 页原文：非<strong>高级会员及以上</strong>会报 <code>The model GLM does not work with your current plan or api key</code>。先核对 Cursor 自己的订阅，再核对 Base URL 是否为 <code>https://open.bigmodel.cn/api/coding/paas/v4</code>，模型名是否按该页要求使用大写。</p>`,53)])])}const F=s(n,[["render",o]]);export{m as __pageData,F as default};
